// ── Core combinatorics functions ─────────────────────────────
function factorial(n) {
  if (n <= 1) return 1;
  return n * factorial(n - 1);
}

function permutations(n, r) {
  // P(n,r) = n! / (n-r)!
  return factorial(n) / factorial(n - r);
}

function combinations(n, r) {
  // C(n,r) = n! / (r! * (n-r)!)
  // Use symmetry: pick smaller r to reduce computation
  r = Math.min(r, n - r);
  return factorial(n) / (factorial(r) * factorial(n - r));
}

function combinationsWithRep(n, r) {
  // Stars and bars: C(n+r-1, r)
  return combinations(n + r - 1, r);
}

// ── Worked examples ───────────────────────────────────────────
console.log('Gold/silver/bronze from 10 athletes:');
console.log('  P(10,3) =', permutations(10, 3)); // 720

console.log('Committee of 3 from 10 people:');
console.log('  C(10,3) =', combinations(10, 3)); // 120

console.log('Each committee counted', factorial(3), 'times in permutations');
console.log('  720 / 6 =', 720 / 6); // 120 — matches

console.log('Poker hands (5 from 52):');
console.log('  C(52,5) =', combinations(52, 5)); // 2598960

console.log('Ice cream scoops (3 from 10, repetition allowed):');
console.log('  C(12,3) =', combinationsWithRep(10, 3)); // 220

// ── Symmetry check ────────────────────────────────────────────
console.log('Symmetry: C(100,97) === C(100,3)?',
  combinations(100, 97) === combinations(100, 3)); // true

// ── Count subsets via binomial theorem ────────────────────────
// Sum of C(n,k) for k=0..n = 2^n (total subsets of n-element set)
const n = 10;
const totalSubsets = Array.from({length: n + 1}, (_, k) => combinations(n, k))
  .reduce((a, b) => a + b, 0);
console.log(`Total subsets of a ${n}-element set:`, totalSubsets); // 1024
console.log('Which equals 2^10:', Math.pow(2, n)); // 1024

// ── Pascal's triangle: DP approach, avoids large factorials ──
function buildPascal(rows) {
  const tri = [[1]];
  for (let n = 1; n < rows; n++) {
    const prev = tri[n - 1];
    const row = [1];
    for (let k = 1; k < n; k++) {
      row.push(prev[k - 1] + prev[k]); // C(n,k) = C(n-1,k-1) + C(n-1,k)
    }
    row.push(1);
    tri.push(row);
  }
  return tri;
}

const pascal = buildPascal(8);
pascal.forEach((row, n) => {
  const sum = row.reduce((a, b) => a + b, 0);
  console.log(`n=${n}: [${row.join(', ')}]  sum=${sum}=2^${n}`);
});
// n=5: [1, 5, 10, 10, 5, 1]  sum=32=2^5

// ── Inclusion-exclusion: multiples of 2, 3, or 5 up to 100 ──
function countMultiples(n, d) { return Math.floor(n / d); }

const N = 100;
const [A, B, C] = [2, 3, 5].map(d => countMultiples(N, d));
const [AB, AC, BC] = [[2,3],[2,5],[3,5]].map(([a,b]) => countMultiples(N, a*b));
const ABC = countMultiples(N, 2*3*5);
const result = A + B + C - AB - AC - BC + ABC;
console.log(`Multiples of 2, 3, or 5 up to 100: ${result}`); // 74

// ── Birthday collision probability ────────────────────────────
function pCollision(k, days = 365) {
  let pNone = 1;
  for (let i = 0; i < k; i++) {
    pNone *= (days - i) / days;
  }
  return 1 - pNone;
}

[10, 23, 30, 50, 57].forEach(k => {
  console.log(`k=${k}: P(collision) = ${(pCollision(k) * 100).toFixed(1)}%`);
});
// k=23: ~50.7%  k=57: ~99.0%

// ── Derangements: no letter in correct envelope ───────────────
function derangements(n) {
  // D(n) = (n-1) * (D(n-1) + D(n-2))  with D(1)=0, D(2)=1
  if (n === 1) return 0;
  if (n === 2) return 1;
  let prev2 = 0, prev1 = 1;
  for (let i = 3; i <= n; i++) {
    const curr = (i - 1) * (prev1 + prev2);
    prev2 = prev1;
    prev1 = curr;
  }
  return prev1;
}

for (let n = 1; n <= 8; n++) {
  console.log(`D(${n}) = ${derangements(n)}, n! = ${factorial(n)}, ratio = ${(derangements(n)/factorial(n)).toFixed(4)}`);
}
// Ratio converges to 1/e ≈ 0.3679
